    o+=T(170,190,'шарттарды PLC тексереді, себебін SCADA түсіндіреді','t-s mu')
    return S(340,200,o,'PLC команда алдында төрт шартты тексереді: қорек, авария жоқ, клапан күйі, конфликт жоқ; бәрі орындалса команда өтеді')
