def fig_roles():
    rs=[('Көру','тек ақпаратты қарайды'),('Оператор','жабдықты басқарады'),('Инженер','параметрлерді өзгертеді'),('Әкімші','жүйелік баптауларға қол жеткізеді')];o=''
    for i,(a,b) in enumerate(rs):
        y=8+i*38;o+=B(10,y,92,28,a,'bxa','t-s t-b',4)+TL(112,y+18,b,'t-s')
    o+=A(326,12,326,142,'lna','hda')+T(300,160,'құқық көбейеді','t-s ac')
    o+=B(10,170,320,30,'Әр әрекет пайдаланушы атымен журналға жазылады','bx','t-s',4)
    return S(340,210,o,'Төрт рөл: көру, оператор, инженер, әкімші; әр әрекет пайдаланушы атымен журналға жазылады')
f_roles=F(fig_roles(),'Пайдаланушы рөлдері: құқық сатылап көбейеді')

